# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: AI Gateway spending limits from Logfire's management API (read-only): the
#          organization's and a project's daily / weekly / monthly caps, to show spend against.
#          Needs the Pydantic API key with organization:read_gateway (`ds settings sync`).
# Usage: limits = spending_limits("delulu-smash") -> SpendingLimits (3 GET requests).
# ---------------------------------------------------------------------------
from __future__ import annotations

from dataclasses import dataclass
from http import HTTPStatus
from typing import Any

from ds.settings import get_settings
from ds.util import http

__all__ = ["GatewayScopeError", "Limits", "SpendingLimits", "spending_limits"]

# ds::external-source: checked 2026-11-17 https://logfire-us.pydantic.dev/api/openapi.json
#   taken from it: GET /v1/projects/, GET /v1/gateway/spending-limits/ and
#   /v1/gateway/spending-limits/projects/{project_id}/ (scope organization:read_gateway),
#   returning {daily_usd, weekly_usd, monthly_usd}: whole US dollars, null = no limit
# ds::external-source: checked 2026-11-17 https://pydantic.dev/docs/logfire/manage/ai-gateway/
#   taken from it: organization and project caps both apply (either blocks); the docs don't
#   say when the windows reset (assumed UTC calendar day / week / month, unverified)
API_URL = "https://logfire-us.pydantic.dev/api"  # US region, like the Gateway (ds.settings)
SOURCE = "logfire"
SCOPE = "organization:read_gateway"


class GatewayScopeError(RuntimeError):
    """The stored key can't read Gateway settings (it lacks organization:read_gateway)."""


@dataclass(frozen=True)
class Limits:
    """One level's caps in whole US dollars; None is no limit."""

    daily: int | None = None
    weekly: int | None = None
    monthly: int | None = None

    def get(self, window: str) -> int | None:
        """The cap for 'daily', 'weekly' or 'monthly'."""
        return getattr(self, window)


@dataclass(frozen=True)
class SpendingLimits:
    """The caps on one project's Gateway requests: its own and the organization's."""

    organization: Limits
    project: Limits
    project_name: str

    def tightest(self, window: str) -> tuple[int | None, str]:
        """The cap that blocks first in a window, and whose it is (project or organization)."""
        levels = ((self.project.get(window), "project"), (self.organization.get(window), "organization"))
        caps = [(cap, who) for cap, who in levels if cap is not None]
        return min(caps) if caps else (None, "")


def _get(path: str, name: str) -> Any:
    key = get_settings().pydantic_gateway_api_key
    if key is None:
        raise GatewayScopeError("No Pydantic API key: run `ds settings sync`.")
    headers = {"Authorization": f"Bearer {key.get_secret_value()}"}
    with http.request("GET", f"{API_URL}{path}", source=SOURCE, name=name, headers=headers) as (resp, _):
        if resp.status_code == HTTPStatus.FORBIDDEN:
            raise GatewayScopeError(f"The Pydantic API key can't read spending limits (needs {SCOPE}).")
        resp.raise_for_status()
        return resp.json()


def _limits(data: dict[str, Any]) -> Limits:
    return Limits(daily=data.get("daily_usd"), weekly=data.get("weekly_usd"), monthly=data.get("monthly_usd"))


def spending_limits(project_name: str) -> SpendingLimits:
    """The organization's caps and those of the project named `project_name`.

    Raises GatewayScopeError when the key can't read them, LookupError for an unknown project,
    and httpx2's errors for anything else (eg a 429).
    """
    projects = _get("/v1/projects/", "projects")
    project = next((p for p in projects if p.get("project_name") == project_name), None)
    if project is None:
        raise LookupError(f"No Logfire project named {project_name!r}.")
    return SpendingLimits(
        organization=_limits(_get("/v1/gateway/spending-limits/", "org spending limits")),
        project=_limits(_get(f"/v1/gateway/spending-limits/projects/{project['id']}/", "project spending limits")),
        project_name=project_name,
    )
